        {"구절":"삼상 12:23", "연결점":"너희를 위하여 기도하기를 쉬는 죄를 여호와 앞에 결코 범하지 않겠다 — 기도하지 않는 것이 죄", "구분":"구약"},
        {"구절":"느 1:4-11", "연결점":"느헤미야가 예루살렘을 위해 금식하며 기도함 — 감사와 간구가 연결된 기도", "구분":"구약"},
        {"구절":"시 34:1", "연결점":"내가 여호와를 항상 송축함이여 그를 찬양함이 내 입에 계속하리로다 — 그치지 않는 감사와 찬양", "구분":"구약"},
        {"구절":"롬 1:9", "연결점":"내가 내 심령으로 섬기는 하나님이 나의 증인이 되시거니와 항상 내 기도에 너희를 기억하며 — 바울의 로마 교인을 위한 기도", "구분":"신약"},
        {"구절":"빌 1:3-4", "연결점":"내가 너희를 생각할 때마다 나의 하나님께 감사하며 — 바울의 빌립보 교인을 위한 감사 기도", "구분":"신약"},
        {"구절":"살전 5:17-18", "연결점":"쉬지 말고 기도하라 범사에 감사하라 — 그치지 않는 기도와 감사", "구분":"신약"},
        {"구절":"히 7:25", "연결점":"그가 항상 살아서 저희를 위하여 간구하심이니라 — 그리스도의 영원한 중보 기도", "구분":"신약"}
