        {"상황":"교회가 충분하지 않다며 이 교회 저 교회를 옮겨다니는 성도", "성경원리":"교회의 충만함은 그리스도로부터 오는 것이지 완벽한 프로그램이나 설교에서 오는 것이 아님", "실제적용":"그리스도를 찾는 것과 완벽한 교회를 찾는 것의 차이를 가르치고, 지금 있는 교회에서 그리스도를 찾고 섬기도록 안내"},
        {"상황":"교회 사역에 지쳐 번아웃된 성도", "성경원리":"교회를 충만케 하시는 분은 그리스도이시므로, 사역자의 역할은 자신의 힘으로 채우는 것이 아닌 그리스도의 충만함을 흘려보내는 것임", "실제적용":"사역의 동기와 방법을 재검토하고, 자신의 힘이 아닌 그리스도의 충만함에서 나오는 사역을 위해 영적 재충전(기도, 말씀, 안식)의 방법을 안내"}
