        {"구절":"겔 37:1-14", "연결점":"마른 뼈들이 살아나는 환상 — 영적으로 죽은 이스라엘의 회복 예언, 중생의 예표", "구분":"구약"},
        {"구절":"사 59:2", "연결점":"너희 죄악이 너희와 너희 하나님 사이를 내었고 — 죄로 인한 하나님과의 단절(영적 죽음)", "구분":"구약"},
        {"구절":"렘 31:33-34", "연결점":"새 언약으로 마음에 율법을 기록하고 죄를 사함 — 영적 살리심의 예언", "구분":"구약"},
        {"구절":"롬 5:12", "연결점":"한 사람으로 말미암아 죄가 세상에 들어오고 죄로 말미암아 사망이 왔나니 — 영적 죽음의 기원", "구분":"신약"},
        {"구절":"요 5:24", "연결점":"내 말을 듣고 또 나 보내신 이를 믿는 자는 영생을 얻었고 사망에서 생명으로 옮겼느니라 — 살리심의 원리", "구분":"신약"},
        {"구절":"롬 6:23", "연결점":"죄의 삯은 사망이요 하나님의 은사는 영생이니 — 죽음과 생명의 대비", "구분":"신약"},
        {"구절":"딛 3:5", "연결점":"우리를 구원하시되 우리의 행한 바 의로운 행위로 말미암지 아니하고 오직 그의 긍휼하심을 좇아 — 구원의 근거가 은혜임", "구분":"신약"}
