        {"구절":"골 3:1-4", "연결점":"그리스도와 함께 일으키심을 받았으면 위의 것을 찾으라 — 하늘에 앉힘의 실천적 함의", "구분":"신약"},
        {"구절":"빌 3:20", "연결점":"우리의 시민권은 하늘에 있는지라 — 성도의 하늘 시민권", "구분":"신약"},
        {"구절":"딤후 2:12", "연결점":"참으면 또한 함께 왕노릇할 것이요 — 그리스도와 함께하는 통치 참여", "구분":"신약"}
