    표8_상담적용: [
        {"상황":"삶이 통제 불가능하게 느껴져 불안한 성도", "성경원리":"하나님은 영원부터 목적을 가지고 역사를 주관하시며 그리스도 안에서 이미 이루셨음 — 역사의 주권자 하나님", "실제적용":"불안의 근원을 탐색하고 하나님의 주권에 대한 신뢰를 재확인하는 상담; 과거의 하나님의 신실하심을 되돌아보기"},
        {"상황":"자신이 구원받지 못할까 봐 두려워하는 성도", "성경원리":"영원부터 예정하신 뜻은 변하지 않으며 그리스도 안에서 이미 이루어진 확실한 구원 (엡 1:4-5)", "실제적용":"구원의 확실성을 하나님의 영원한 목적에 근거하여 가르침; 느낌이 아닌 하나님의 말씀에 근거한 구원 확신 훈련"},
        {"상황":"인생의 방향을 잃고 방황하는 성도", "성경원리":"하나님은 영원부터 그리스도 안에서 우리를 향한 목적을 갖고 계심 — 방황이 아닌 목적 있는 삶", "실제적용":"하나님의 부르심과 목적을 발견하는 여정 돕기; 삶의 사건들을 하나님의 목적의 일부로 재해석"}
    ],
