        {"구절":"빌 1:27", "연결점":"복음에 합당하게 생활하라 — 에베소서 4:1과 평행 표현", "구분":"신약"},
        {"구절":"골 1:10", "연결점":"주께 합당하게 행하여 — 합당한 삶의 구체적 내용", "구분":"신약"},
        {"구절":"살전 2:12", "연결점":"하나님 나라에 합당하게 행하게 하신다 — 부르심의 목적", "구분":"신약"}
