        {"항목":"니케아 신조의 선구적 형태", "내용":"4-6절의 '하나'의 선언은 이후 니케아 신조(AD 325)의 '우리는 하나의 거룩한 보편적 사도적 교회를 믿는다'의 신학적 기초이다", "목회적활용":"우리의 신앙은 사도들로부터 이어진 보편적 신앙이다"}
