        {"교리":"그리스도의 주 되심", "설명":"예수 그리스도는 유일한 주이시다. 이것이 기독교 신앙의 핵심이다. 많은 주 중 하나가 아니라 유일한 주이시다(행 4:12)", "관련구절":"행 4:12, 빌 2:9-11, 롬 10:9, 고전 8:6"},
        {"교리":"신앙의 객관성", "설명":"'하나의 믿음'은 주관적 신앙 경험의 다양성이 아닌 믿음의 객관적 내용(복음)의 통일성을 가리킨다. 구원은 동일한 복음에 대한 동일한 신앙으로 이루어진다", "관련구절":"유 1:3, 갈 1:9, 딤전 4:6, 딛 1:4"},
        {"교리":"세례의 의미", "설명":"세례는 그리스도와의 연합을 상징하며(롬 6:3-4) 교회 공동체 편입의 표징이다. 하나의 세례가 모든 성도의 동일한 지위를 선언한다", "관련구절":"롬 6:3-4, 갈 3:27, 행 2:38, 마 28:19"}
