        {"구분":"이스라엘의 하나의 율법", "내용":"하나의 율법이 이스라엘 모든 지파에게 동일하게 적용되었다", "그리스도연결":"하나의 복음이 모든 민족에게 동일하게 선포된다 (갈 3:28)"}
