        {"대지":"2대지: 하나의 믿음 — 내용의 통일성", "내용":"믿음이 하나라는 것은 신앙의 내용이 동일하다는 것이다. 같은 복음, 같은 예수, 같은 구원. 표현 방식은 달라도 믿음의 핵심은 동일하다", "예화_적용":"같은 언어의 다른 방언들 — 발음이 달라도 같은 언어이다"},
        {"대지":"3대지: 하나의 세례 — 편입의 통일성", "내용":"세례는 교파를 초월하여 그리스도의 몸에 편입되는 하나의 의식이다. 누가 어디서 세례를 받든 그것은 동일한 그리스도 안으로의 편입이다", "예화_적용":"여권이 어떤 나라에서 발급되든 한 나라 국민임을 증명하듯"},
        {"대지":"결론", "내용":"하나의 주, 하나의 믿음, 하나의 세례를 가진 우리는 이미 하나입니다. 교단의 차이, 예배 형식의 차이를 넘어 이 세 가지 하나됨을 기억할 때 우리는 그리스도 안에서 형제임을 재발견합니다", "예화_적용":"같은 아버지를 둔 형제들은 사이가 나빠도 가족이다"}
