        {"항목":"스토아 철학의 만유 개념", "내용":"당시 스토아 철학에서도 '만유 위에, 만유를 통해, 만유 안에'라는 표현을 사용했다. 바울은 이 철학 언어를 사용하여 삼위 하나님의 초월성과 내재성을 선언한다", "목회적활용":"복음은 문화의 언어를 사용하되 그 내용을 전복시킨다"},
        {"항목":"유대교의 유일신 신앙", "내용":"유대교의 핵심인 '하나님은 하나이시다'(신 6:4)를 신약은 그리스도와 성령을 포함하는 삼위일체로 발전시킨다", "목회적활용":"구약의 유일신 신앙이 신약에서 풍성하게 계시된다"}
