        {"새찬송가":"500", "통일찬송가":"349", "제목":"내게 있는 모든 것을", "선정이유":"받은 은사를 드리는 헌신"},
        {"새찬송가":"207", "통일찬송가":"165", "제목":"성령이 오셔서", "선정이유":"성령의 은사로 교회를 세워주시길 기도"},
        {"새찬송가":"595", "통일찬송가":"251", "제목":"주의 일을 내가 하오리", "선정이유":"받은 은사를 주의 일에 사용하는 헌신"}
