        {"상황":"자신의 은사를 찾지 못해 좌절하는 성도", "성경원리":"승천하신 그리스도가 각 사람에게 선물을 주셨다 — 받지 못한 것이 아니라 발견하지 못한 것", "실제적용":"공동체 안에서 자연스럽게 흘러나오는 섬김을 관찰하라. 기도하며 성령의 인도를 구하라"},
        {"상황":"그리스도의 능력을 의심하는 성도", "성경원리":"그리스도는 사로잡힌 자를 사로잡을 만큼 강하신 분이다", "실제적용":"시편 68편을 묵상하라. 승전하신 하나님의 능력이 당신의 삶에도 동일하게 역사하심을 믿으라"}
