        {"상황":"삶이 내려가는 것 같아 두려운 성도", "성경원리":"내려가는 것이 항상 나쁜 것이 아니다 — 그리스도도 내려가셨다가 올라가셨다", "실제적용":"지금의 내려가는 시간이 하나님의 훈련 과정일 수 있다. 요셉의 이야기처럼 준비의 시간이다"}
