        {"구분":"엘리야의 승천", "내용":"불 수레와 불 말들로 엘리야가 하늘로 올라감(왕하 2:11)", "그리스도연결":"그리스도의 승천은 성경에 예언된 최고의 하늘 상승 — 구름을 타고 올라가심 (행 1:9)"},
        {"구분":"하나님의 영광이 성전에 충만함", "내용":"솔로몬 성전 낙성식에 하나님의 영광이 충만하여 제사장이 설 수 없었다(왕상 8:10-11)", "그리스도연결":"승천하신 그리스도가 성령으로 교회를 충만케 하신다(엡 1:23)"}
