        {"교리":"사도와 선지자의 기초적 역할", "설명":"교회는 사도들과 선지자들의 터 위에 세워졌다(엡 2:20). 사도와 선지자는 신약 계시를 받아 기록한 기초 직분으로, 그 역할은 신약 정경 안에 완성되었다", "관련구절":"엡 2:20, 계 21:14, 고전 12:28, 행 11:27-28"},
        {"교리":"복음 전도자와 목사-교사의 지속성", "설명":"복음 전도자, 목사, 교사는 사도 시대 이후에도 교회에 지속되는 직분이다. 이 직분들을 통해 그리스도가 계속 교회를 세우신다", "관련구절":"딤후 4:5, 딤전 3:2, 딛 1:9, 행 14:23"}
