        {"구분":"이드로의 제안 — 천부장, 백부장, 오십부장, 십부장", "내용":"모세가 홀로 재판하는 부담을 분담하기 위해 다양한 직급의 지도자를 세움(출 18:21)", "그리스도연결":"그리스도가 교회 사역을 분담할 다양한 직분자들을 세우셔서 교회를 온전케 하신다"},
        {"구분":"아론의 제사장직과 레위인들", "내용":"대제사장 아론과 다양한 역할을 담당한 레위인들이 성막 사역을 분담했다", "그리스도연결":"참된 대제사장이신 그리스도가 다양한 사역자들을 통해 교회를 섬기신다 (히 7:24-25)"}
