    표5_매튜헨리: [
        {"영어원문":"He gave some, apostles — the chief ministers, who had the greatest authority and the fullest gifts.", "한국어번역":"혹은 사도로 주셨으니 — 가장 큰 권위와 가장 풍성한 은사를 가진 수석 사역자들이다.", "핵심통찰":"사도는 교회의 기초를 놓는 역할 — 그 기초 위에 교회가 세워진다"},
        {"영어원문":"Pastors and teachers — some think these are the same persons, as the word and seems to join them.", "한국어번역":"목사와 교사 — 일부는 이 둘이 동일한 사람들로 본다. '와'라는 접속사가 이들을 연결하는 것 같기 때문이다.", "핵심통찰":"가르치는 목사가 교회의 핵심 직분 — 말씀 사역이 목회의 본질이다"},
        {"영어원문":"The church is enriched with various gifts for its edification — each minister has his proper place.", "한국어번역":"교회는 세워지기 위해 다양한 은사로 풍성하게 되었다 — 각 사역자는 자신의 고유한 자리가 있다.", "핵심통찰":"다양한 직분의 협력이 교회를 풍성하게 한다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"그리스도가 교회에 주신 다섯 가지 선물 — 사역자들", "예화_적용":"몸에 각기 다른 기관들이 있어 생명이 유지되듯 — 교회에 다양한 직분들이 있어 교회가 세워진다"},
        {"대지":"서론", "내용":"그리스도가 교회에 가장 소중한 선물을 주셨습니다. 그것은 황금도 건물도 아닙니다. 바로 사역자들입니다. 사도, 선지자, 복음 전도자, 목사, 교사 — 이들이 그리스도가 교회에 주신 선물입니다", "예화_적용":"좋은 선생님을 받은 학교가 얼마나 복된가 — 그리스도가 좋은 사역자를 주심이 교회의 가장 큰 복이다"},
        {"대지":"1대지: 사도와 선지자 — 기초를 놓는 직분", "내용":"사도와 선지자는 신약 계시를 받아 교회의 기초를 놓았다(엡 2:20). 우리는 지금도 그 기초 위에 서 있다. 신약 성경이 사도적 권위의 유산이다", "예화_적용":"집의 기초는 한 번만 놓아지면 충분하다 — 사도와 선지자의 기초 위에 교회가 영원히 세워진다"},
        {"대지":"2대지: 복음 전도자 — 경계를 넘는 직분", "내용":"복음 전도자(에우앙겔리스타스)는 새 지역과 새 사람에게 복음을 전하는 선교적 사역자이다. 경계를 넘어 복음을 전하는 용기 있는 직분이다", "예화_적용":"개척자처럼 — 복음 전도자는 아직 복음이 가지 않은 곳을 향해 달려간다"},
        {"대지":"3대지: 목사와 교사 — 세우는 직분", "내용":"목사는 양 떼를 먹이고 돌보는 목자이다. 교사는 말씀으로 가르치는 자이다. 이 두 역할이 지역 교회를 세우는 핵심이다. 좋은 목사-교사가 있는 교회는 복된 교회이다", "예화_적용":"농부가 씨를 뿌리고 물을 주고 잡초를 뽑듯 — 목사와 교사가 말씀으로 성도를 세운다"},
        {"대지":"결론", "내용":"사역자들을 위해 기도합시다. 그들은 그리스도가 교회에 주신 선물입니다. 동시에 모든 성도들도 자신의 역할과 직분을 발견하여 교회를 세우는 데 참여해야 합니다. 모든 지체가 역할을 할 때 교회가 자랍니다", "예화_적용":"좋은 팀의 모든 선수가 각자의 포지션에서 최선을 다할 때 팀이 이기듯 — 모든 지체가 제 역할을 할 때 교회가 이긴다"}
    ],
