        {"상황":"자신이 어떤 사역에 부르심을 받았는지 모르는 성도", "성경원리":"다양한 직분이 있다 — 모든 사람이 목사가 될 필요는 없다. 각자의 은사에 맞는 사역이 있다", "실제적용":"현재 자연스럽게 이끌리는 섬김의 영역을 찾으라. 복음 전도, 가르침, 돌봄 중 무엇에 열정이 있는가?"},
        {"상황":"교회 사역자들에 대한 불신이 있는 성도", "성경원리":"사역자들은 그리스도가 주신 선물이다 — 완전하지 않지만 그리스도의 선물이다", "실제적용":"사역자의 인간적 약함과 그리스도가 주신 직분의 권위를 구분하라. 직분을 존중하되 우상화하지 말라"}
