        {"상황":"교리 공부가 왜 필요한지 모르는 성도", "성경원리":"교리 교육이 이단 방어이다 — 어린아이처럼 무지하면 속기 쉽다", "실제적용":"교회의 교리 교육 프로그램에 참여하라. 웨스트민스터 소요리문답이나 사도신경을 공부하라"}
