        {"상황":"신앙 성장이 없는 것 같아 낙심한 성도", "성경원리":"범사에 그에게까지 자랄지라 — 성장은 과정이다", "실제적용":"매일 말씀 묵상과 기도를 통해 그리스도와 대화하라. 측정하기 어려운 성장도 일어나고 있다. 방향이 맞으면 속도는 부차적이다"}
