        {"상황":"선의의 거짓말을 자주 하는 성도", "성경원리":"거짓을 버리라 — 사랑으로 포장된 거짓도 거짓이다", "실제적용":"불편한 진실을 사랑으로 말하는 방법을 연습하라. 15절의 '사랑 안에서 진리를 말하라'가 원리이다"},
        {"상황":"교회 내에서 험담과 거짓 소문이 있는 공동체", "성경원리":"우리가 서로 지체이다 — 지체에 대한 거짓은 자신을 해치는 것이다", "실제적용":"험담을 들었을 때 퍼뜨리지 말고 당사자에게 직접 확인하라. 진실한 소통이 공동체를 건강하게 한다"}
