    표5_매튜헨리: [
        {"영어원문":"Be ye angry, and sin not — some degree of anger, on some occasions, is not sinful.", "한국어번역":"분을 내어도 죄를 짓지 말라 — 어떤 경우에 어느 정도의 분노는 죄가 아니다.", "핵심통찰":"분노 자체가 죄가 아님을 성경이 인정한다 — 그러나 그 경계가 중요하다"},
        {"영어원문":"Let not the sun go down upon your wrath — do not let it rest and settle in you.", "한국어번역":"분을 해가 지도록 품지 말라 — 분이 당신 안에 자리잡고 고이게 하지 말라.", "핵심통찰":"분노는 빨리 해결해야 한다 — 굳어지기 전에 다루어야 한다"},
        {"영어원문":"Linger not in your passion, for that gives the devil an advantage over you.", "한국어번역":"분 안에 오래 머물지 말라. 그것이 마귀에게 당신에 대한 이점을 주기 때문이다.", "핵심통찰":"오래된 분노가 마귀의 도구가 된다 — 빠른 용서가 영적 자기 보호이다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"분노를 죄가 되기 전에 끊으라 — 분노 관리의 성경적 원리", "예화_적용":"불꽃은 빨리 끄면 화재가 되지 않지만 오래 두면 집을 태운다 — 분노도 빨리 다스려야 한다"},
        {"대지":"서론", "내용":"'분을 내어도 죄를 짓지 말며.' 놀라운 말씀입니다. 분노해도 된다는 허락인가요? 네, 분노는 죄가 아닙니다. 예수님도 분노하셨습니다. 그러나 분노가 죄로 발전하지 않도록 다스려야 합니다", "예화_적용":"불이 난로 안에 있을 때는 따뜻하지만 방 밖으로 나오면 화재가 된다 — 분노도 적절하게 다스려져야 한다"},
        {"대지":"1대지: 분노 자체는 죄가 아니다", "내용":"시편 4:4를 인용하여 분노를 허용한다. 불의에 대한 의로운 분노는 하나님의 성품이기도 하다. 예수님의 성전 청결이 그 예이다. 억압된 분노가 더 위험할 수 있다. 분노는 문제가 있다는 신호이다", "예화_적용":"고통이 신체 문제의 신호이듯 — 분노는 관계나 상황의 문제의 신호이다"},
        {"대지":"2대지: 분을 내어도 죄를 짓지 말라", "내용":"분노와 죄 사이의 경계선이 있다. 이 경계를 지켜야 한다. 말로 상처를 주거나, 복수하거나, 관계를 끊거나, 하나님의 명령을 어기면 분노가 죄가 된다. 분노의 온도를 낮추는 연습이 필요하다", "예화_적용":"핵 반응이 제어되면 에너지가 되지만 제어되지 않으면 폭발이 되듯"},
        {"대지":"3대지: 해가 지도록 분을 품지 말라", "내용":"시간적 한계를 주신다. 분노를 하루 이상 끌지 말라. 빠른 화해와 용서가 분노를 죄로 발전시키지 않는다. 오늘 해결하지 못한 분노는 내일 더 커진다. 지금 가서 화해하라(마 5:23-24)", "예화_적용":"음식은 빨리 먹어야 상하지 않듯 — 분노는 빨리 해결해야 썩지 않는다"},
        {"대지":"결론", "내용":"지금 누군가에게 분노가 있습니까? 오늘 해가 지기 전에 해결하십시오. 먼저 가서 화해를 시도하십시오. 용서를 구하거나 용서를 베푸십시오. 분노를 내일로 미루지 마십시오. 내일의 분노는 오늘보다 더 무겁습니다", "예화_적용":"빚은 이자가 붙어 커진다 — 분노도 시간이 지날수록 더 다루기 어려워진다"}
    ],
