        {"영어원문":"The grace of God teaches us to use the things of this world for the benefit of others as well as ourselves.", "한국어번역":"하나님의 은혜는 우리에게 이 세상의 것을 자신뿐 아니라 다른 사람의 유익을 위해 사용하도록 가르친다.", "핵심통찰":"소유는 나눔을 통해 비로소 은혜의 통로가 됨"}
