        {"항목":"바울의 권면적 말하기 방식", "내용":"바울 서신 전체는 공동체를 세우는 언어의 모범을 보여주며, 그는 설득과 격려와 권면의 말을 통해 교회를 이끌었다", "목회적활용":"목회자의 언어 사역을 성찰하고 공동체를 세우는 말하기의 모범을 보이도록 촉구"}
