        {"구절":"롬 8:26-27", "연결점":"성령이 우리의 연약함을 도우시며 간구하신다", "구분":"신약"},
        {"구절":"요 14:16-17", "연결점":"영원히 함께 하실 보혜사 성령을 약속하심", "구분":"신약"}
