        {"상황":"교회 내 갈등으로 인해 비방하고 험담하는 그룹이 생긴 경우", "성경원리":"비방은 공동체를 파괴하는 중대한 죄이며 회개와 화해 없이는 공동체 회복이 불가능하다", "실제적용":"갈등 당사자들의 직접 대화 중재, 목회자의 중재 역할, 공동체 화해의 절차 마련"}
