        {"구절":"시 103:12", "연결점":"동이 서에서 먼 것같이 죄를 멀리하신 하나님의 용서", "구분":"구약"},
        {"구절":"미 7:18-19", "연결점":"죄를 발 아래 밟으시고 바다 깊이 던지시는 하나님의 용서", "구분":"구약"},
        {"구절":"마 18:21-35", "연결점":"일만 달란트 탕감받은 자의 비유, 용서받은 자의 용서 의무", "구분":"신약"},
        {"구절":"골 3:13", "연결점":"주께서 용서하신 것같이 서로 용서하라는 동일한 명령", "구분":"신약"},
        {"구절":"눅 23:34", "연결점":"십자가에서의 용서 기도, 그리스도 용서의 모범", "구분":"신약"},
        {"구절":"롬 5:8", "연결점":"우리가 아직 죄인 되었을 때 그리스도가 죽으심으로 하나님의 사랑이 확증됨", "구분":"신약"}
