        {"상황":"크리스천으로서 삶의 목표가 불분명한 성도", "성경원리":"그리스도인의 삶의 목표는 하나님을 본받아 그분을 닮아가는 것이다", "실제적용":"하나님의 성품 목록 만들기, 매달 하나씩 실천하는 성화 훈련 계획 수립"},
        {"상황":"부모와의 관계 문제로 하나님 아버지 이미지가 왜곡된 성도", "성경원리":"하나님은 완전한 아버지이시며, 인간 아버지와는 다른 완전한 사랑과 수용을 주신다", "실제적용":"상처받은 내면아이 치유 상담, 하나님 아버지 이미지 재구성 작업, 시 103편 묵상"}
