        {"대지":"2대지: 책망하라 (적극적 증언)", "내용":"엘렝케테 - 증거로 드러내라. 빛이 어둠을 만나면 자연스럽게 어둠이 드러난다. 우리의 거룩한 삶 자체가 어둠을 책망하는 증거가 된다.", "예화_적용":"직장에서 부정직한 관행을 거부하는 삶 자체로 동료들에게 영향을 미친 성도의 간증"},
        {"대지":"3대지: 책망의 방법 (사랑의 용기)", "내용":"책망은 정죄가 아니다. 진리를 사랑으로 말하는 것이다. 두려움 없이, 그러나 따뜻하게 진리를 말하는 것이 빛의 자녀의 책임이다.", "예화_적용":"친구의 잘못된 관계에 사랑으로 진실을 말해준 성도가 그 친구를 살린 이야기"},
        {"대지":"결론", "내용":"어둠 앞에서 침묵하는 것은 어둠에 동참하는 것이다. 오늘 빛을 비추라. 거룩한 삶으로, 용기 있는 말로, 사랑의 행동으로.", "예화_적용":"오늘 주변의 어둠에 작은 빛을 비추는 한 가지 실천으로 마무리"}
