        {"항목":"수치 문화의 사회적 기능", "내용":"그레코-로마 사회에서 수치(아이스코스)는 사회적 통제 기능을 했으나, 바울은 이를 넘어 하나님 앞에서의 수치를 기준으로 제시한다", "목회적활용":"사회적 평판이 아닌 하나님 앞에서의 부끄러움이 진정한 도덕의 기준임을 가르침"}
