        {"원어":"파네로우타이 (φανεροῦται)", "의미_문법":"나타나다, 드러나다 - 현재 수동 직설법, 숨겨진 것이 밝아지는 과정", "설교포인트":"빛은 숨겨진 것을 드러내어 본래의 모습을 보이게 한다"},
        {"원어":"파네로우메논 (φανερούμενον)", "의미_문법":"나타내어지는 것 - 현재 수동 분사, 빛으로 드러나는 것 자체가 빛이 된다는 역설", "설교포인트":"어둠도 빛에 노출되면 빛의 일부가 된다는 변화의 역설은 회개와 성화의 신학적 기초이다"}
