    표2_역사적배경: [
        {"항목":"빛의 의학적 사용", "내용":"고대 세계에서 썩은 상처를 치유하는 방법 중 하나가 햇빛에 노출시키는 것이었다. 빛이 감염을 막고 치유를 돕는다는 이해가 있었다", "목회적활용":"죄를 고백하고 빛에 드러내는 것이 영적 상처를 치유하는 과정임을 설명하는 의학적 비유"},
        {"항목":"플라톤의 동굴 비유", "내용":"플라톤의 동굴 비유에서 동굴 속 그림자를 실체로 알고 사는 자들이 빛을 보면 처음에는 눈이 아프지만 결국 진리를 보게 된다는 비유는 바울의 빛 신학과 공명한다", "목회적활용":"진리의 빛이 처음에는 불편하지만 결국 자유를 준다는 신앙의 역설 설교"}
    ],
    표3_신학적의미: [
        {"교리":"계시론", "설명":"하나님의 빛은 숨겨진 것을 드러내시는 계시의 능력이며, 말씀과 성령을 통해 우리 삶의 죄와 잘못을 드러내신다", "관련구절":"시 119:130, 히 4:12-13, 요 1:4-5"},
        {"교리":"구원론", "설명":"드러남은 심판이 아닌 구원의 과정이며, 죄가 드러날 때 회개와 치유가 가능하다. 빛은 정죄가 아닌 변화의 도구이다", "관련구절":"요 8:32, 요일 1:7-9, 시 32:5"},
        {"교리":"성화론", "설명":"성화는 빛이 계속해서 어둠의 구석구석을 드러내고 정결케 하는 과정이며, 이 과정이 반복되며 점진적으로 이루어진다", "관련구절":"고후 3:18, 요일 1:7, 요 15:3"}
    ],
    표4_예표론: [
        {"구분":"레위기 제사의 진단과 치유", "내용":"레위기 13장에서 제사장이 문둥병(피부 질환)을 진단하여 격리하고 치유 여부를 확인하는 과정은 빛으로 드러내어 치유하는 예표", "그리스도연결":"그리스도는 참된 대제사장으로 우리의 영적 질병을 진단하시고, 그 피로 깨끗하게 하신다"},
        {"구분":"이사야의 하나님의 빛", "내용":"이사야 60:1에서 일어나라 빛을 발하라, 네 빛이 이르고 여호와의 영광이 네 위에 임하였음이라는 선포는 하나님의 빛이 어둠을 몰아내는 예언", "그리스도연결":"예수님은 이 예언의 성취이시며(요 8:12), 그의 빛이 임할 때 모든 어둠이 드러나고 빛으로 변한다"}
    ],
    표5_매튜헨리: [
        {"영어원문":"But all things that are reproved are made manifest by the light: for whatsoever doth make manifest is light.", "한국어번역":"그러나 책망을 받는 모든 것이 빛으로 말미암아 나타나나니, 나타내어지는 것마다 빛이니라.", "핵심통찰":"빛의 기능은 드러내는 것이며, 드러내어지는 것이 빛의 일부가 된다는 역설"},
        {"영어원문":"When the works of darkness are made manifest by the light, they lose their power and influence, and those who did them are ashamed.", "한국어번역":"어둠의 행위들이 빛으로 드러날 때, 그것들은 능력과 영향력을 잃게 되고, 그것들을 행한 자들은 수치를 당한다.", "핵심통찰":"드러남이 어둠의 권세를 무너뜨린다"},
        {"영어원문":"The change of sinners into saints is made by the light of the gospel working powerfully upon them.", "한국어번역":"죄인이 성도로 변화되는 것은 복음의 빛이 그들에게 능력 있게 역사함으로 이루어진다.", "핵심통찰":"복음의 빛이 인간의 어둠을 빛으로 변화시키는 능력이다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"드러남이 치유이다", "예화_적용":"의사의 진단이 두려워 병원을 피하다가 결국 더 악화된 사람처럼, 죄를 빛 앞에 드러내지 않으면 더 깊어진다"},
        {"대지":"서론", "내용":"드러남은 두렵다. 그러나 바울은 놀라운 역설을 말한다. 드러나는 것이 빛이 된다. 책망을 통해 드러난 것들이 치유를 경험한다.", "예화_적용":"수술이 두렵지만 수술로만 나을 수 있는 질병처럼, 드러남만이 치유의 시작이다"},
        {"대지":"1대지: 빛의 드러내는 능력", "내용":"빛은 어둠을 판단하지 않는다. 그냥 비출 뿐이다. 그 비춤 자체가 어둠을 드러낸다. 말씀의 빛, 성령의 빛, 공동체의 빛이 우리 삶의 어둠을 드러낸다.", "예화_적용":"성경 읽다가 자신의 죄가 명확히 보여 충격받은 성도의 이야기"},
        {"대지":"2대지: 드러남의 역설 (나타난 것이 빛)", "내용":"놀라운 역설이다. 드러나는 것마다 빛이 된다. 죄가 고백으로 드러날 때 그 고백 자체가 빛의 일부가 된다. 드러남이 심판이 아닌 치유와 변화의 시작이다.", "예화_적용":"고백 후에 '도리어 마음이 가벼워졌다'는 성도들의 경험"},
        {"대지":"3대지: 변화의 능력 (어둠도 빛이 된다)", "내용":"이것이 복음의 능력이다. 어둠이 빛에 노출될 때 빛이 된다. 죄인이 그리스도의 빛에 노출될 때 성도가 된다. 가장 깊은 어둠도 복음 앞에서 빛으로 변화될 수 있다.", "예화_적용":"가장 어두운 과거를 가진 자가 가장 강력한 빛의 증거자가 된 간증"},
        {"대지":"결론", "내용":"두려워 숨기지 말라. 빛 앞에 드러내라. 드러냄이 치유의 시작이다. 성령의 빛, 말씀의 빛, 공동체의 빛 앞에 나아오라.", "예화_적용":"오늘 하나님 앞에 한 가지를 고백하고 드러내는 기도로 마무리"}
    ],
