        {"상황":"남의 죄를 드러내어 상처를 주고 공동체를 분열시킨 성도", "성경원리":"책망은 사랑의 동기로 개인적으로 먼저 하는 것이며, 공개적 폭로는 치유가 아닌 상처를 준다", "실제적용":"책망의 성경적 방법 교육(마 18:15-17), 동기 점검, 공동체 회복을 위한 사과와 화해"}
