        {"원어":"엔 오노마티 토우 쿠리우 (ἐν ὀνόματι τοῦ κυρίου)", "의미_문법":"주의 이름으로 - 그리스도의 권위와 공로를 통해 감사를 드림", "설교포인트":"우리의 감사가 주님께 상달될 수 있는 것은 오직 예수 그리스도의 이름을 통해서이다"}
