        {"교리":"삼위일체론", "설명":"예수 그리스도의 이름으로 아버지 하나님께 감사하며 성령 충만의 결과로 드리는 감사는 삼위일체 하나님께 드려지는 예배이다", "관련구절":"롬 1:8, 고전 15:57, 요 16:23-24"},
        {"교리":"예배론", "설명":"감사는 예배의 핵심 행위이며, 범사에 드리는 감사가 삶 전체를 예배로 만든다", "관련구절":"시 100:4, 히 13:15, 고후 4:15"}
