        {"구분":"다윗의 항상 감사", "내용":"시편 34:1 '내가 여호와를 항상 송축함이여'는 고난 중에도 지속되는 다윗의 감사를 보여줌", "그리스도연결":"그리스도는 완전한 감사의 제물이 되셨으며(히 7:27), 그 안에서 우리의 모든 감사가 아버지께 상달된다"}
