    표5_매튜헨리: [
        {"영어원문":"Husbands, love your wives, even as Christ also loved the church, and gave himself for it.", "한국어번역":"남편들아 아내 사랑하기를 그리스도께서 교회를 사랑하시고 그를 위하여 자신을 주심같이 하라.", "핵심통찰":"그리스도의 십자가 사랑이 남편 사랑의 기준이며 이것은 매우 높은 기준이다"},
        {"영어원문":"The measure of the husband's love must be the measure of Christ's love for the church.", "한국어번역":"남편의 사랑의 척도는 교회를 향한 그리스도의 사랑의 척도여야 한다.", "핵심통찰":"자기희생까지 감수하는 사랑이 남편에게 요구되는 것이다"},
        {"영어원문":"Christ gave himself for the church — not merely his money, his time, or his labor — but himself.", "한국어번역":"그리스도는 교회를 위해 자신을 주셨다. 단지 그의 돈이나 시간이나 수고만이 아니라 그 자신을.", "핵심통찰":"진정한 사랑은 것들을 주는 것이 아닌 자기 자신을 주는 것이다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"십자가를 기준으로 삼는 남편 사랑", "예화_적용":"등산할 때 정상을 기준으로 삼는 것처럼, 남편의 사랑의 기준은 그리스도의 십자가이다"},
        {"대지":"서론", "내용":"남편들이여, 당신의 아내 사랑의 기준은 무엇인가? 좋은 남편들의 기준? 소셜미디어의 기준? 바울은 충격적인 기준을 제시한다. 그리스도가 교회를 위해 자신을 주심같이 하라.", "예화_적용":"높은 기준 앞에서 도전받는 남편들의 솔직한 자기 점검"},
        {"대지":"1대지: 사랑의 성격 (아가페)", "내용":"아가파테 - 아가페로 사랑하라. 이것은 감정의 사랑이 아니다. 상대방의 자격과 무관하게 선택하는 의지적 사랑이다. 아내가 사랑받을 자격이 있어서가 아니라, 사랑하기로 선택하는 것이다.", "예화_적용":"아내가 아플 때, 상처를 줄 때도 사랑하기로 결단한 남편의 이야기"},
        {"대지":"2대지: 사랑의 기준 (그리스도의 자기헌신)", "내용":"파레도켄 - 자신을 주셨다. 십자가는 완전한 자기헌신이다. 남편의 사랑도 자기 편의, 자기 시간, 자기 욕구를 아내를 위해 포기하는 자기헌신이어야 한다.", "예화_적용":"아내의 꿈을 위해 자신의 승진 기회를 포기한 남편의 이야기"},
        {"대지":"3대지: 사랑의 대상 (불완전한 아내)", "내용":"그리스도는 완전한 교회를 위해 죽지 않으셨다. 죄인인 우리를 위해 죽으셨다. 남편의 사랑도 완벽한 아내를 위한 조건부 사랑이 아닌, 있는 그대로의 아내를 사랑하는 것이다.", "예화_적용":"아내의 약점에도 불구하고 변함없이 사랑을 선택한 남편의 결혼 30주년 간증"},
        {"대지":"결론", "내용":"남편 된 이여, 당신의 사랑은 십자가를 향해 있는가? 완벽하지 않아도 된다. 오늘 한 걸음 더 십자가의 방향으로 나아가라.", "예화_적용":"오늘 아내를 위해 자신의 무언가를 희생하는 구체적 사랑의 실천으로 마무리"}
    ],
