        {"대지":"서론", "내용":"현대 사회에서 부부 갈등과 이혼율이 급증하는 이유 중 하나는 사랑의 기준이 감정에 기반하기 때문이다. 바울은 흔들리지 않는 기준, 곧 '자기 몸같이'를 제시한다", "예화_적용":"결혼 상담 사례: 감정이 식었다며 이혼을 요구하는 남편과 상담한 목사의 이야기"},
        {"대지":"1대지: 몸의 사랑 (자기 보존 본능)", "내용":"인간은 본능적으로 자기 몸을 돌본다. 배고프면 먹이고, 아프면 치료한다. 바울은 이 본능적 사랑을 아내에게 적용하라고 명한다", "예화_적용":"추운 날 자신은 따뜻하게 입으면서 아내는 춥게 두는 남편의 불일치를 지적하라"},
        {"대지":"2대지: 연합의 사랑 (존재론적 하나됨)", "내용":"아내를 사랑하는 것이 자기를 사랑하는 것인 이유는 결혼이 두 사람을 한 몸으로 만들기 때문이다. 이는 계약이 아닌 연합이다", "예화_적용":"장기 이식 후 두 사람이 하나가 되듯, 결혼은 삶의 공유와 동일시를 만든다"},
        {"대지":"3대지: 그리스도의 사랑 (모델과 동력)", "내용":"그리스도께서 교회를 자신의 몸처럼 사랑하신 것이 남편 사랑의 모델이다. 이 사랑은 인간의 본능을 초월하여 그리스도의 사랑에서 힘을 얻는다", "예화_적용":"순교자 폴리갑이 성도를 위해 목숨 버린 사랑처럼, 남편은 아내를 위한 희생에서 기쁨을 찾아야 한다"},
        {"대지":"결론", "내용":"아내를 사랑하는 남편은 결국 자기를 사랑하는 것이다. 가정의 행복은 남편이 얼마나 자기 몸처럼, 그리고 그리스도처럼 아내를 사랑하느냐에 달려 있다", "예화_적용":"기도 제목: 내 아내를 내 몸같이 사랑하는 은혜를 달라고 매일 기도하기"}
