        {"구분":"오셋의 어미 새 이미지", "내용":"독수리가 새끼를 날개로 덮어 보호하는 신명기의 이미지는 탈포(따뜻하게 보호)의 원형이다", "그리스도연결":"그리스도께서 우리를 날개 아래 품으시는 보호자 (마 23:37)"},
        {"구분":"요셉의 형제 양육", "내용":"요셉이 기근 중에 형제들을 양육한 것은 희생적 돌봄과 보호의 예표다", "그리스도연결":"그리스도께서 우리의 필요를 채우시는 공급자 (빌 4:19)"}
