    표5_매튜헨리: [
        {"영어원문":"Christ nourishes and cherishes the church by his word and ordinances, by the influences of his Spirit, and by all the comforts he affords.", "한국어번역":"그리스도께서는 말씀과 규례를 통해, 성령의 영향을 통해, 그리고 그분이 주시는 모든 위로를 통해 교회를 양육하고 소중히 여기신다.", "핵심통찰":"남편이 아내를 양육하는 것은 그리스도께서 교회를 돌보시는 총체적 사역을 모방하는 것이다"},
        {"영어원문":"We naturally nourish and cherish our bodies; in like manner we should love our wives.", "한국어번역":"우리는 본능적으로 우리 몸을 양육하고 소중히 여긴다. 이와 같이 우리는 아내를 사랑해야 한다.", "핵심통찰":"자기 몸 돌봄의 본능을 아내 사랑의 기준으로 삼는 것은 자연스럽고 당연한 의무다"},
        {"영어원문":"The husband ought to be as tender of his wife as of his own flesh, and as careful of her welfare as of his own.", "한국어번역":"남편은 자기 살만큼 아내를 부드럽게 대하고, 자기 복지를 돌보듯 아내의 안녕을 염려해야 한다.", "핵심통찰":"양육과 보호는 물질적 공급만이 아니라 정서적 민감성과 세심한 배려를 포함한다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"양육하고 보호하라 — 그리스도처럼 돌보는 남편", "예화_적용":"어버이날이나 가정 회복 집회에 적합"},
        {"대지":"서론", "내용":"현대 사회에서 많은 남편들이 경제적 공급자 역할은 알아도 정서적 보호자 역할을 놓친다. 바울은 양육(ektrepho)과 보호(thalpo)라는 두 단어로 남편의 총체적 돌봄을 명한다", "예화_적용":"직장에서는 부하 직원을 세심하게 챙기면서 집에서 아내는 무심히 대하는 남편의 이중성 이야기"},
        {"대지":"1대지: 양육 (ektrepho — 먹이고 키우기)", "내용":"양육은 아내의 신체적, 정서적, 영적 필요를 지속적으로 채우는 것이다. 그리스도께서 말씀과 성례로 교회를 양육하시듯 남편은 말씀과 기도로 아내를 양육해야 한다", "예화_적용":"매주 아내와 함께 성경 한 구절 나누는 부부 큐티 사례"},
        {"대지":"2대지: 보호 (thalpo — 따뜻하게 품기)", "내용":"탈포는 어미 새가 알을 품듯 따뜻한 정서적 안전 지대를 만드는 것이다. 아내가 상처받지 않도록 지키고, 세상의 차가움으로부터 보호하는 것이 남편의 역할이다", "예화_적용":"아내가 직장에서 상처받고 돌아왔을 때 공감과 위로로 품은 남편의 실화"},
        {"대지":"3대지: 그리스도의 모델 (교회 돌봄의 기준)", "내용":"그리스도께서 교회를 양육하고 보호하시는 것이 남편 사랑의 최고 기준이다. 이 사랑은 인간 본성을 초월하지만 성령 안에서 가능하다", "예화_적용":"선교지에서 아내를 희생적으로 섬긴 선교사 부부의 간증"},
        {"대지":"결론", "내용":"아내를 양육하고 보호하는 남편은 그리스도를 닮아가는 성화의 과정 중에 있다. 가정이 천국의 작은 모형이 되려면 남편이 먼저 그리스도처럼 섬겨야 한다", "예화_적용":"기도 결단: 이번 주 아내에게 구체적 양육과 보호의 행동 한 가지 실천하기"}
    ],
