        {"항목":"유대 사상의 공동체 이해", "내용":"유대교에서 이스라엘은 하나님의 몸(공동체)으로서 집단적 정체성이 강했다. 바울은 이를 신약의 교회론으로 발전시켰다", "목회적활용":"구약의 이스라엘과 신약의 교회의 연속성과 차이를 가르치는 자료로 활용"},
        {"항목":"에베소 교회 분열 상황", "내용":"유대인과 이방인이 공존하는 에베소 교회에서 '우리는 하나의 몸'이라는 선언은 분열을 넘는 연합의 신학적 기초를 제공했다", "목회적활용":"교회 내 갈등 상황에서 그리스도 안의 연합을 강조하는 설교 자료로 활용"}
