        {"구분":"룻의 시어머니 나오미에 대한 순종", "내용":"룻이 자기 민족과 부모를 떠나 나오미를 따른 것은 헌신적 공경의 예표다", "그리스도연결":"교회가 그리스도의 권위에 자발적으로 복종하는 신앙의 예표 (엡 5:24)"}
