        {"대지":"1대지: 순종의 대상 (부모 — 하나님의 대리 권위)", "내용":"부모는 하나님이 가정에 세우신 대리 권위자이다. 부모에게 순종하는 것은 하나님의 권위 구조를 인정하는 것이다", "예화_적용":"부모를 공경함으로 하나님을 공경하는 믿음을 배운 어린 시절 신앙 간증"},
        {"대지":"2대지: 순종의 방식 (주 안에서 — 신앙적 순종)", "내용":"주 안에서의 순종은 단순한 복종이 아니라 하나님을 섬기는 마음으로 하는 신앙적 행위이다. 이 훈련이 평생 신앙의 기초가 된다", "예화_적용":"어릴 때 부모 섬김을 배운 사람이 성인이 되어 하나님을 잘 섬기는 상관관계"},
        {"대지":"3대지: 순종의 근거 (이것이 옳으니라 — 창조 질서)", "내용":"부모 순종이 옳은 이유는 하나님의 명령이며 자연법이며 사회적 질서이기 때문이다. 세 가지 근거 모두 순종의 필연성을 지지한다", "예화_적용":"부모를 공경하지 않는 문화에서 가정과 사회가 무너진 역사적 사례"},
        {"대지":"결론", "내용":"자녀들아, 주 안에서 부모에게 순종하라. 이 작은 순종이 하나님을 섬기는 연습이 되고, 평생 권위에 건강하게 반응하는 인격을 형성한다", "예화_적용":"기도 제목: 부모를 주께 하듯 공경하게 해달라는 자녀들의 기도"}
