        {"상황":"부모가 하나님 뜻에 반하는 것을 요구하는 자녀 상담", "성경원리":"주 안에서라는 한정어는 부모가 하나님 뜻에 반하는 것을 명할 때 순종하지 않아도 됨을 의미한다. 하나님께 먼저 순종해야 한다", "실제적용":"사도행전 5:29의 원칙 가르치기, 부모와 건강한 대화 방법 안내"}
