        {"상황":"부모와의 관계가 상처로 가득한 성인 자녀 상담", "성경원리":"부모 공경은 완벽한 부모를 전제하지 않는다. 상처 있는 관계에서도 용서와 공경을 선택하는 것이 성경적 부름이다", "실제적용":"부모 용서 기도 훈련, 내적 치유 사역 연결, 건강한 경계선 안에서의 공경 방법 안내"},
        {"상황":"부모와 배우자 사이에서 갈등하는 기혼 자녀 상담", "성경원리":"결혼 후에도 부모 공경은 지속되지만(5:31의 떠남과 구별), 배우자가 먼저임을 분명히 해야 한다", "실제적용":"부모와의 건강한 경계선 설정 돕기, 배우자와 부모 모두를 존중하는 구체적 방법 안내"}
