        {"항목":"헬라-로마 세계의 장수 이해", "내용":"고대 세계에서 장수는 하늘의 복의 표시로 여겨졌다. 바울은 이 보편적 관념을 하나님의 약속으로 확인한다", "목회적활용":"부모 공경이 사회 안정과 개인 번영에 미치는 영향을 역사적으로 가르치는 자료로 활용"},
        {"항목":"약속의 조건부 성격", "내용":"이 약속은 무조건적 보장이 아니라 하나님의 일반적 섭리 안에서의 복의 원리이다. 예외 사례도 있지만 하나님의 일반적 축복 패턴을 보여준다", "목회적활용":"하나님의 약속이 기계적 법칙이 아닌 인격적 관계 안에서 이루어짐을 가르치는 자료로 활용"}
