        {"영어원문":"Those who are governed by the eye of men will be inconsistent; those governed by God's eye will be consistent.", "한국어번역":"사람의 눈에 의해 다스림을 받는 자들은 일관성이 없을 것이고, 하나님의 눈에 의해 다스림을 받는 자들은 일관성이 있을 것이다.", "핵심통찰":"진정한 직업 윤리의 일관성은 인간의 감시가 아닌 하나님의 전지하심에 대한 신앙에서 온다"}
