pastorCommentaryData["에베소서_6_21"] = {
    본문: "너희도 나의 일과 나의 어떻게 지내는 것을 알려면 주 안에서 사랑을 받는 형제요 신실한 일꾼인 두기고가 모든 일을 너희에게 알게 하리니",
    표1_원어분석: [
        {"원어":"튀키코스 (Τύχικος)", "의미_문법":"두기고 - 인명, 행운스러운이라는 의미의 헬라식 이름", "설교포인트":"두기고는 실제 인물로 바울의 편지를 전달하는 신실한 동역자였다. 복음 사역에서 보이지 않는 동역자들의 중요성을 보여준다"},
        {"원어":"아가페토스 아델포스 카이 피스토스 디아코노스 엔 퀴리오 (ἀγαπητὸς ἀδελφὸς καὶ πιστὸς διάκονος ἐν Κυρίῳ)", "의미_문법":"사랑받는 형제요 신실한 일꾼 - 두 가지 성품적 특성으로 소개", "설교포인트":"사랑받는 형제(인격)와 신실한 일꾼(사역) — 바울이 두기고를 묘사하는 두 차원이 좋은 사역자의 기준을 보여준다"},
        {"원어":"에이스 아우토 투토 (εἰς αὐτὸ τοῦτο)", "의미_문법":"이 일을 위해 - 목적을 나타내는 표현, 두기고를 보내는 구체적 목적", "설교포인트":"두기고를 보내는 목적이 분명하다 — 소식 전달과 위로. 사역에는 분명한 목적이 있어야 한다"}
    ],
    표2_역사적배경: [
        {"항목":"두기고의 인물 배경", "내용":"두기고는 아시아(소아시아) 출신으로 바울의 제3차 선교 여행에 동참했다(행 20:4). 에베소서, 골로새서, 디모데후서에 등장하는 신실한 사역자이다", "목회적활용":"보이지 않는 곳에서 신실하게 사역하는 동역자들의 중요성을 가르치는 자료로 활용"},
        {"항목":"고대의 편지 전달 체계", "내용":"고대에는 우편 제도가 없었으므로 신뢰할 수 있는 사람이 직접 편지를 전달했다. 두기고는 단순한 우편부가 아니라 편지의 맥락을 설명해줄 수 있는 신뢰받는 사역자였다", "목회적활용":"복음 전달에 있어 전달자의 신뢰성과 인격이 얼마나 중요한지 가르치는 자료로 활용"},
        {"항목":"바울의 동역자 네트워크", "내용":"바울의 사역은 혼자가 아닌 두기고, 에바브라, 아리스다고, 데마 등 수많은 동역자들과 함께 이루어졌다. 복음 사역은 팀 사역이다", "목회적활용":"복음 사역에서 팀워크와 공동체의 중요성을 가르치는 자료로 활용"}
    ],
    표3_신학적의미: [
        {"교리":"사역자의 인격과 사역의 통합", "설명":"사랑받는 형제(인격)와 신실한 일꾼(사역)은 분리될 수 없다. 인격 없는 사역은 위험하고 사역 없는 인격은 무익하다", "관련구절":"딤전 3:1-7, 딛 1:6-9, 행 6:3"},
        {"교리":"공동체적 사역", "설명":"바울이 두기고를 보내어 소식을 전하는 것은 복음 사역이 개인이 아닌 공동체 안에서 이루어짐을 보여준다", "관련구절":"고전 12:27-28, 롬 12:4-5, 엡 4:11-12"},
        {"교리":"주 안에서의 관계", "설명":"두기고를 주 안에서 사랑받는 형제라고 부르는 것은 신앙 공동체의 관계가 주 안에서 형성되고 유지됨을 보여준다", "관련구절":"빌 4:1, 몬 1:16, 롬 16:22"}
    ],
    표4_예표론: [
        {"구분":"요나단과 다윗의 신실한 우정", "내용":"요나단이 위험을 무릅쓰고 다윗을 도운 것이 신실한 동역자의 원형이다", "그리스도연결":"그리스도께서 우리를 친구라 부르시며 생명을 주신 신실한 동역자의 최고 모범 (요 15:13-15)"},
        {"구분":"바룩과 예레미야의 동역", "내용":"바룩이 예레미야의 말씀을 기록하고 전달한 것이 복음 전달자 두기고의 역할과 유사한 신실한 동역의 예표이다", "그리스도연결":"그리스도의 복음 전달에 신실하게 참여하는 동역자들의 사역 (고전 3:9)"},
        {"구분":"느헤미야의 팀 사역", "내용":"느헤미야가 혼자가 아닌 팀으로 성벽을 재건한 것이 복음 공동체 사역의 예표이다", "그리스도연결":"하나님의 교회가 팀으로 세워지는 것 (엡 4:11-13)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"Tychicus was a dear brother and faithful minister — faithful in discharging his ministerial duties, and dear to Paul for his fidelity.", "한국어번역":"두기고는 사랑받는 형제요 신실한 일꾼이었다 — 목회적 의무를 수행하는 데 신실하고 그 신실함으로 바울에게 사랑스러운 자였다.", "핵심통찰":"신실함이 사랑받음의 근거이다. 신실한 사역자가 공동체에서 사랑받는다"},
        {"영어원문":"Paul sends Tychicus to inform them of his state, that they might know how to pray for him.", "한국어번역":"바울은 두기고를 보내어 자신의 상황을 알려 성도들이 어떻게 기도해야 할지 알게 하려 했다.", "핵심통찰":"정보 공유가 올바른 중보기도를 가능하게 한다. 사역자의 상황을 아는 성도가 더 효과적으로 기도할 수 있다"},
        {"영어원문":"To know the affairs of another is necessary for the comfort both of those who communicate and those who receive the intelligence.", "한국어번역":"다른 사람의 일을 아는 것은 전달하는 자와 받는 자 모두의 위로를 위해 필요하다.", "핵심통찰":"정보 공유는 단순한 소통이 아니라 공동체의 위로와 연대를 위한 필수 요소이다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"신실한 동역자 두기고 — 보이지 않는 곳에서 섬기는 자들의 아름다움", "예화_적용":"교회 헌신자 감사 예배, 봉사자 헌신 예배, 사역 주일에 적합"},
        {"대지":"서론", "내용":"에베소서의 화려한 신학 뒤에 두기고라는 이름이 나온다. 바울의 편지를 전달한 무명의 동역자. 교회에는 이런 두기고들이 있다. 보이지 않는 곳에서 신실하게 섬기는 자들이다", "예화_적용":"교회 청소, 주차 안내, 주방 봉사 등 눈에 띄지 않는 봉사를 30년 하신 집사님의 이야기"},
        {"대지":"1대지: 사랑받는 형제 (인격의 기초)", "내용":"두기고가 사랑받는 이유는 그의 인격이다. 신실한 인격이 먼저이고 사역은 그다음이다. 인격 없는 사역자는 결국 공동체를 해친다", "예화_적용":"능력은 있지만 인격이 없어 교회를 해친 사역자와 인격으로 사역한 두기고 대조"},
        {"대지":"2대지: 신실한 일꾼 (사역의 일관성)", "내용":"두기고는 신실한 일꾼이었다. 신실함은 화려함이 아닌 일관성이다. 큰 무대보다 작은 일에서 일관되게 섬기는 것이 신실한 일꾼이다", "예화_적용":"30년간 매주 같은 자리에서 같은 섬김을 드린 집사님의 신실함이 결국 교회를 세운 이야기"},
        {"대지":"3대지: 위로를 전달하는 자 (공동체의 연결고리)", "내용":"두기고의 역할은 소식 전달과 위로였다. 공동체 안에서 서로의 소식을 전하고 위로하는 것이 교회를 살아있게 하는 일이다", "예화_적용":"아픈 성도를 방문하고 소식을 전달하며 공동체를 연결하는 구역장의 사역"},
        {"대지":"결론", "내용":"당신 교회의 두기고는 누구인가? 보이지 않는 곳에서 신실하게 섬기는 그들을 기억하고 감사하라. 그리고 당신도 두기고가 되라", "예화_적용":"기도 결단: 보이지 않는 봉사자들을 위해 기도하고 감사를 표현하겠다는 결단"}
    ],
    표7_찬송가: [
        {"새찬송가":"438", "통일찬송가":"399", "제목":"내 너를 위하여", "선정이유":"그리스도를 위해 신실하게 섬기는 헌신을 고백하는 찬송"},
        {"새찬송가":"501", "통일찬송가":"457", "제목":"내 주의 나라와", "선정이유":"주의 나라를 위해 신실하게 섬기겠다는 헌신의 찬송"},
        {"새찬송가":"580", "통일찬송가":"515", "제목":"나의 갈 길 다 가도록", "선정이유":"끝까지 신실하게 사명을 감당하겠다는 헌신의 찬송"},
        {"새찬송가":"559", "통일찬송가":"496", "제목":"주 안에 있는 나에게", "선정이유":"주 안에서의 사랑과 신실한 섬김의 기쁨을 노래하는 찬송"}
    ],
    표8_상담적용: [
        {"상황":"인정받지 못하는 봉사로 지친 성도 상담", "성경원리":"두기고처럼 주 안에서 사랑받는 것이 진정한 인정이다. 사람의 인정보다 하나님과 공동체 안에서의 인정이 더 중요하다", "실제적용":"봉사의 동기를 주를 향한 것으로 재설정, 공동체 안에서 감사를 표현하는 문화 만들기"},
        {"상황":"자신의 봉사가 의미없다고 느끼는 성도 상담", "성경원리":"두기고의 편지 전달처럼 작은 일이 큰 사역을 완성시킨다. 어떤 봉사도 하나님 나라에서 의미없는 것은 없다", "실제적용":"자신의 봉사가 공동체에 미치는 영향 파악하기, 작은 섬김의 의미와 가치를 발견하는 묵상"},
        {"상황":"팀으로 사역하기 어렵다고 하는 사역자 상담", "성경원리":"바울도 두기고 없이는 사역을 완성할 수 없었다. 혼자 모든 것을 하려는 것은 교만이며 두기고 같은 동역자를 세우는 것이 지혜이다", "실제적용":"동역자의 강점 파악하기, 권한 위임 훈련, 팀 사역의 기쁨 발견하기"}
    ],
    표9_교차참조: [
        {"구절":"행 20:4", "연결점":"두기고가 바울의 아시아 출신 동역자로 제3차 선교 여행에 함께했다는 역사적 기록", "구분":"구약"},
        {"구절":"삼상 18:1-4", "연결점":"요나단과 다윗의 신실한 우정이 신실한 동역자의 구약 원형", "구분":"구약"},
        {"구절":"느 3:1-32", "연결점":"느헤미야의 성벽 재건에서 각자의 구역을 신실하게 맡아 일한 팀 사역의 예표", "구분":"구약"},
        {"구절":"렘 36:4-18", "연결점":"바룩이 예레미야의 말씀을 기록하고 전달한 신실한 동역자의 역할의 예표", "구분":"구약"},
        {"구절":"골 4:7-8", "연결점":"골로새서에서 두기고에 대한 동일한 소개 — 사랑받는 형제요 신실한 일꾼이요 주 안에서 함께된 종", "구분":"신약"},
        {"구절":"딤후 4:12", "연결점":"바울이 두기고를 에베소에 보냈다는 마지막 사역 기록", "구분":"신약"},
        {"구절":"롬 16:1-16", "연결점":"바울의 동역자들에 대한 감사 목록 — 복음 사역이 팀 사역임을 보여주는 신약의 예", "구분":"신약"},
        {"구절":"빌 4:3", "연결점":"함께 복음을 위해 힘쓴 동역자들의 이름이 생명책에 있다 — 신실한 동역자의 영원한 가치", "구분":"신약"}
    ]
};

pastorCommentaryData["에베소서_6_22"] = {
    본문: "내가 저를 이 일로 너희에게 보낸 것은 너희로 하여금 우리 사정을 알고 너희 마음을 위안 받게 하려 함이라",
    표1_원어분석: [
        {"원어":"에페프사 아우톤 프로스 휘마스 에이스 아우토 투토 (ἔπεμψα αὐτὸν πρὸς ὑμᾶς εἰς αὐτὸ τοῦτο)", "의미_문법":"이 일을 위해 저를 너희에게 보냈다 - 부정과거, 결단적 행동, 목적이 분명한 파송", "설교포인트":"바울은 두기고를 보낸 목적을 두 가지로 말한다: 사정을 알게 함과 마음을 위로함. 사역에는 분명한 목적이 있어야 한다"},
        {"원어":"히나 그노테 타 페리 헤몬 (ἵνα γνῶτε τὰ περὶ ἡμῶν)", "의미_문법":"우리 사정을 알게 하려 함이라 - 목적절, 정보 전달의 목적", "설교포인트":"공동체 안에서 서로의 사정을 아는 것이 연대와 기도를 가능케 한다"},
        {"원어":"파라카레세 타스 카르디아스 휘몬 (παρακαλέσῃ τὰς καρδίας ὑμῶν)", "의미_문법":"너희 마음을 위안 받게 하려 함 - 파라카레오(위로하다, 격려하다), 마음의 위로가 목적", "설교포인트":"파라카레오는 옆에서 부르는 것으로 위로와 격려를 동시에 의미한다. 사역의 궁극적 목표가 마음의 위로이다"}
    ],
    표2_역사적배경: [
        {"항목":"바울의 구금과 성도들의 걱정", "내용":"에베소 성도들은 바울이 로마에 구금되었다는 소식을 들었을 것이다. 두기고의 방문은 그 걱정을 해소하고 실제 상황을 알려주는 목적이 있었다", "목회적활용":"성도들이 사역자를 위해 걱정하고 기도하는 것이 공동체의 자연스러운 돌봄임을 가르치는 자료로 활용"},
        {"항목":"파라클레시스의 넓은 의미", "내용":"파라클레시스(위로, 격려)는 신약에서 매우 중요한 단어이다. 성령은 파라클레토스(보혜사, 위로자)이며 바울은 고난받는 성도들을 위로하는 사역을 강조했다(고후 1:3-4)", "목회적활용":"위로의 사역이 복음 사역의 핵심임을 가르치는 자료로 활용"},
        {"항목":"편지와 사신을 통한 위로", "내용":"고대에 멀리 있는 공동체를 위로하는 것은 편지와 사신을 통해 이루어졌다. 두기고는 편지를 전달하면서 동시에 직접 방문으로 성도들을 위로했다", "목회적활용":"현대에도 편지(이메일, 메시지)와 방문이 공동체 위로의 중요한 방법임을 가르치는 자료로 활용"}
    ],
    표3_신학적의미: [
        {"교리":"공동체의 돌봄", "설명":"서로의 사정을 알고 마음을 위로하는 것이 그리스도의 몸인 교회의 본질적 기능이다. 위로는 복음 전파만큼 중요한 사역이다", "관련구절":"고후 1:3-4, 롬 12:15, 살전 4:18"},
        {"교리":"정보 공유와 공동체 연대", "설명":"서로의 사정을 아는 것이 효과적인 중보기도와 실질적 돌봄을 가능케 한다. 정보의 공유가 공동체의 연대를 강화한다", "관련구절":"고전 12:26, 빌 4:14, 롬 15:30-32"},
        {"교리":"위로의 사역", "설명":"고난받는 자를 위로하는 것은 하나님의 성품의 반영이다(고후 1:3). 위로의 사역은 복음의 실천적 차원이다", "관련구절":"고후 1:3-7, 사 61:2, 마 5:4"}
    ],
    표4_예표론: [
        {"구분":"요나단의 다윗 위로", "내용":"요나단이 광야에서 도망 중인 다윗을 찾아가 그 손을 힘있게 하였다는 것이 위로의 방문의 원형이다", "그리스도연결":"그리스도께서 성령을 보내어 우리를 위로하시는 보혜사의 사역 (요 14:16)"},
        {"구분":"나오미와 룻의 위로", "내용":"룻이 나오미를 떠나지 않고 함께 함으로 위로한 것이 공동체 안에서의 위로의 예표이다", "그리스도연결":"그리스도께서 우리와 함께 계셔서 위로하시는 임마누엘의 사역 (마 1:23)"},
        {"구분":"욥의 친구들의 첫 방문 (긍정적 면)", "내용":"욥의 친구들이 처음에 함께 앉아 침묵으로 함께한 것은 고난받는 자와 함께하는 위로의 예표이다", "그리스도연결":"고난 중에 우리와 함께하시는 그리스도의 연대 (히 4:15)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"He sent him to comfort their hearts; the news of a friend's welfare is comforting, especially when they have been in any distress.", "한국어번역":"그는 그들의 마음을 위로하려고 두기고를 보냈다. 친구의 안녕에 대한 소식은 위로가 된다. 특히 그들이 어떤 곤경에 처해 있을 때는 더욱 그러하다.", "핵심통찰":"멀리 있는 사랑하는 자의 안녕 소식이 공동체의 걱정을 해소하고 위로를 가져다준다"},
        {"영어원문":"The real concern of ministers for those under their charge is one of the greatest comforts these can receive.", "한국어번역":"사역자들이 자신의 책임 아래 있는 자들에 대해 진정으로 관심을 갖는 것은 그들이 받을 수 있는 가장 큰 위로 중 하나이다.", "핵심통찰":"목자가 양을 진심으로 걱정하고 있다는 것을 아는 것 자체가 양에게 큰 위로가 된다"},
        {"영어원문":"It is the duty of Christians to comfort each other, and to communicate such intelligence as may be serviceable for that end.", "한국어번역":"기독교인의 의무는 서로 위로하는 것이며, 그 목적을 위해 도움이 될 수 있는 정보를 전달하는 것이다.", "핵심통찰":"위로는 감정적 공감만이 아니라 적절한 정보와 소식 공유를 통해서도 이루어진다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"너희 마음을 위안 받게 하려 함이라 — 공동체 안에서의 위로 사역", "예화_적용":"위기에 처한 성도를 위한 예배, 공동체 회복 예배, 봉사자 감사 예배에 적합"},
        {"대지":"서론", "내용":"바울은 신학을 마치고 마지막에 두기고를 소개한다. 그 목적은 마음의 위로이다. 복음의 최종 목적지는 이론이 아니라 사람의 마음이다", "예화_적용":"훌륭한 설교를 들었지만 위로받지 못한 사람과 간단한 방문으로 큰 위로를 받은 사람 대조"},
        {"대지":"1대지: 서로의 사정을 알라 (정보 공유와 기도)", "내용":"우리 사정을 알게 하려 함이다. 서로의 사정을 모르면 효과적으로 기도할 수 없고 위로할 수 없다. 공동체 안에서 서로의 상황을 나누는 것이 위로의 시작이다", "예화_적용":"소그룹 나눔에서 서로의 기도 제목을 알고 기도하는 공동체의 위로 효과"},
        {"대지":"2대지: 마음을 위로하라 (파라카레오 — 옆에서 부르기)", "내용":"위로는 멀리서 말로 하는 것이 아니라 옆에 있어주는 것에서 시작된다. 두기고는 편지로 끝내지 않고 직접 방문했다. 임재가 위로이다", "예화_적용":"문자 메시지로 위로하려는 것과 직접 방문하는 위로의 차이"},
        {"대지":"3대지: 위로를 보내라 (두기고를 보냄 — 위로의 사신)", "내용":"바울은 자신이 갈 수 없을 때 두기고를 보냈다. 위로가 필요한 곳에 위로하는 사람을 보내는 것도 위로 사역이다. 교회는 서로에게 두기고를 보내는 공동체이다", "예화_적용":"아픈 성도를 위해 대신 방문하도록 봉사자를 연결하는 교회 공동체 돌봄 시스템"},
        {"대지":"결론", "내용":"복음은 위로이다. 하나님의 위로를 받은 자는 다른 사람을 위로한다. 오늘 당신 주변의 위로가 필요한 사람에게 두기고가 되어 찾아가라", "예화_적용":"기도 결단: 이번 주 위로가 필요한 성도를 찾아가거나 연락하겠다는 구체적 결단"}
    ],
    표7_찬송가: [
        {"새찬송가":"492", "통일찬송가":"449", "제목":"내 모든 시험 무거운 짐을", "선정이유":"모든 짐을 주께 맡기는 위로의 찬송으로 힘든 성도들에게 적합"},
        {"새찬송가":"559", "통일찬송가":"496", "제목":"주 안에 있는 나에게", "선정이유":"주 안에서 받는 위로와 평안을 노래하는 찬송"},
        {"새찬송가":"384", "통일찬송가":"427", "제목":"예수가 함께 계시니", "선정이유":"예수가 함께 계시므로 두려움 없이 위로받는 신앙의 찬송"},
        {"새찬송가":"364", "통일찬송가":"401", "제목":"기도하는 이 시간", "선정이유":"기도 중에 하나님의 위로를 받는 시간의 소중함을 노래하는 찬송"}
    ],
    표8_상담적용: [
        {"상황":"공동체 안에서 외롭다고 느끼는 성도 상담", "성경원리":"서로의 사정을 알고 마음을 위로하는 것이 교회의 본질적 기능이다. 외로움은 공동체 안에서의 적극적 자기 공개와 다가감으로 해결된다", "실제적용":"소그룹 참여 권유, 자신의 필요를 나눌 수 있는 안전한 환경 만들기"},
        {"상황":"고난 중에 있는 성도를 어떻게 위로해야 할지 모르는 성도 상담", "성경원리":"위로는 해결책이 아니라 함께함이다. 두기고처럼 옆에 있어주는 것이 가장 강력한 위로이다", "실제적용":"방문 방법 안내, 경청 훈련, 고통 중에 있는 자를 위한 성경 구절 나누기"},
        {"상황":"교회 공동체 안에서 상처받은 성도 상담", "성경원리":"파라카레오(위로)는 다가와서 부르는 것이다. 상처받았어도 공동체가 먼저 위로를 위해 다가올 수 있다. 공동체의 위로 사역이 필요하다", "실제적용":"교회 리더십의 진심 어린 사과와 위로 제공, 상처 치유를 위한 구체적 돌봄 계획"}
    ],
    표9_교차참조: [
        {"구절":"삼상 23:16", "연결점":"요나단이 다윗의 손을 힘있게 하여 하나님을 의지하게 한 위로의 방문의 원형", "구분":"구약"},
        {"구절":"욥 2:11-13", "연결점":"욥의 친구들이 함께 찾아와 침묵으로 함께 앉아 위로한 것 — 함께함이 위로임을 보여주는 예표", "구분":"구약"},
        {"구절":"이사야 61:2", "연결점":"모든 슬픈 자를 위로하게 하려 하심이라 — 위로 사역이 메시아의 사역임을 보여주는 예언", "구분":"구약"},
        {"구절":"시 23:4", "연결점":"주께서 나와 함께 하심이라 주의 지팡이와 막대기가 나를 안위하시나이다 — 함께하심이 위로임", "구분":"구약"},
        {"구절":"고후 1:3-4", "연결점":"하나님은 위로의 하나님이시요 우리가 받은 위로로 다른 자들을 위로하게 하신다 — 위로의 신학적 근거", "구분":"신약"},
        {"구절":"살전 4:18", "연결점":"그러므로 이 여러 말로 서로 위로하라 — 종말론적 소망이 현재의 위로의 근거가 됨", "구분":"신약"},
        {"구절":"골 4:8", "연결점":"두기고를 보낸 목적이 골로새서에서도 동일하게 위로로 기록됨 — 병행 구절", "구분":"신약"},
        {"구절":"요 14:16", "연결점":"내가 다른 보혜사(파라클레토스)를 보내리라 — 성령이 위로자로 오심으로 두기고의 역할을 신학적으로 설명", "구분":"신약"}
    ]
};

pastorCommentaryData["에베소서_6_23"] = {
    본문: "평강과 믿음을 사랑과 아울러 하나님 아버지와 주 예수 그리스도로 좇아 형제들에게 있을지어다",
    표1_원어분석: [
        {"원어":"에이레네 토이스 아델포이스 카이 아가페 메타 피스테오스 (εἰρήνη τοῖς ἀδελφοῖς καὶ ἀγάπη μετὰ πίστεως)", "의미_문법":"평강과 믿음과 사랑이 형제들에게 - 소원문, 세 가지 복음적 덕목의 기원", "설교포인트":"에이레네(평강), 아가페(사랑), 피스티스(믿음)는 에베소서 전체 교훈의 요약이다"},
        {"원어":"아포 테우 파트로스 카이 퀴리우 예수 크리스투 (ἀπὸ θεοῦ πατρὸς καὶ κυρίου Ἰησοῦ Χριστοῦ)", "의미_문법":"하나님 아버지와 주 예수 그리스도로부터 - 출처를 나타내는 전치사 아포", "설교포인트":"모든 영적 복의 출처는 삼위일체 하나님이다. 평강, 사랑, 믿음 모두 하나님으로부터 온다"},
        {"원어":"에스토 (ἔστω)", "의미_문법":"있을지어다 - 현재 명령법 3인칭 단수, 소원적 명령", "설교포인트":"있을지어다는 기원과 명령을 겸한 표현으로 이 복들이 실제 현실이 되기를 바라는 간절한 소원이다"}
    ],
    표2_역사적배경: [
        {"항목":"고대 서신의 결론 형식", "내용":"고대 헬라 서신은 작별 인사(파레로스)로 마무리되었다. 바울은 헬라식 작별 인사를 복음적 축복으로 변환하여 에베소서를 마무리한다", "목회적활용":"일상의 형식도 복음으로 변화시키는 것이 기독교인의 삶의 방식임을 가르치는 자료로 활용"},
        {"항목":"삼위일체적 축복의 신학", "내용":"하나님 아버지와 주 예수 그리스도로부터라는 표현은 삼위일체 하나님이 복의 출처임을 명시한다. 이것은 이미 1:2에서 시작된 삼위일체적 구조가 마지막까지 유지되는 것이다", "목회적활용":"에베소서 전체의 삼위일체적 구조를 마무리하며 가르치는 자료로 활용"},
        {"항목":"형제들에 대한 보편적 축복", "내용":"형제들이라는 호칭은 에베소 교회 성도들과 더 나아가 모든 믿는 자들을 포함한다. 복음의 복은 모든 성도에게 동등하게 주어진다", "목회적활용":"복음의 보편성과 포용성을 가르치는 자료로 활용"}
    ],
    표3_신학적의미: [
        {"교리":"삼위일체 하나님의 복", "설명":"평강, 사랑, 믿음이 하나님 아버지와 주 예수 그리스도로부터 온다는 것은 모든 영적 복의 삼위일체적 원천을 선언한다", "관련구절":"엡 1:2, 고후 13:13, 계 1:4-5"},
        {"교리":"복음의 요약 (평강, 사랑, 믿음)", "설명":"평강(하나님과의 화해), 사랑(아가페 사랑), 믿음(그리스도에 대한 신뢰)은 에베소서 전체의 핵심 주제들의 요약이다", "관련구절":"엡 1:15, 2:14-17, 4:15-16"},
        {"교리":"공동체적 복", "설명":"이 복들이 형제들에게 있을지어다라는 공동체적 차원에서 선포된다. 복음의 복은 개인적이면서 동시에 공동체적이다", "관련구절":"갈 6:10, 엡 2:19, 벧전 2:17"}
    ],
    표4_예표론: [
        {"구분":"아론의 제사장적 축복", "내용":"민수기 6:24-26의 아론의 축복이 평강과 사랑을 빌어주는 것으로 에베소서 마지막 축복의 구약 원형이다", "그리스도연결":"그리스도께서 우리의 대제사장으로서 하나님의 평강과 복을 선물로 주신다 (히 7:25)"},
        {"구분":"야곱의 아들들에 대한 축복", "내용":"야곱이 죽음 앞에서 각 아들에게 축복을 선포한 것이 형제들에게 복을 선언하는 것의 구약 원형이다", "그리스도연결":"그리스도께서 모든 성도에게 하나님 나라의 기업을 선언하시는 것 (엡 1:3-14)"},
        {"구분":"시편의 축복 선언", "내용":"많은 시편이 축복 선언으로 끝나는 것처럼 에베소서도 복음적 축복으로 마무리된다", "그리스도연결":"그리스도 안에서 완성된 모든 복이 성도들에게 선언됨 (엡 1:3)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"Peace be to the brethren, to all who are in Jesus Christ: peace with God, peace with men, peace in their own consciences.", "한국어번역":"형제들에게 평강이 있을지어다, 예수 그리스도 안에 있는 모든 자들에게. 하나님과의 평강, 사람과의 평강, 자신의 양심에서의 평강.", "핵심통찰":"성경적 평강은 세 차원이다: 하나님과의 수직적 화해, 사람들과의 수평적 평화, 내면의 양심의 평화"},
        {"영어원문":"Love with faith — active and operative love, faith making it lively and producing its fruit.", "한국어번역":"믿음을 동반한 사랑 — 활동적이고 작동하는 사랑, 믿음이 그것을 생동감 있게 하고 열매를 맺게 한다.", "핵심통찰":"사랑과 믿음은 함께 작동한다. 믿음이 없는 사랑은 감정에 불과하고 사랑이 없는 믿음은 죽은 것이다"},
        {"영어원문":"From God the Father and the Lord Jesus Christ — these blessings come from the best hand; they are procured by Jesus Christ and communicated by the Father.", "한국어번역":"하나님 아버지와 주 예수 그리스도로부터 — 이 복들은 최선의 손에서 온다. 예수 그리스도가 획득하시고 아버지가 전달하신다.", "핵심통찰":"복의 원천이 삼위일체 하나님이라는 것이 그 복의 신뢰성과 영속성을 보장한다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"평강과 믿음과 사랑이 있을지어다 — 에베소서가 남기는 세 가지 복음적 선물", "예화_적용":"에베소서 강해 마지막 설교, 신년 예배, 성도 파송 예배에 적합"},
        {"대지":"서론", "내용":"에베소서는 하나님의 우주적 계획부터 가정 윤리, 영적 전쟁까지 웅장한 여정을 담았다. 그리고 마지막에 세 가지 선물을 남긴다: 평강, 믿음, 사랑. 이것이 에베소서가 우리에게 주는 선물이다", "예화_적용":"훌륭한 여행을 마치고 집에 가져오는 선물처럼, 에베소서를 읽은 후 가져가야 할 세 가지 선물"},
        {"대지":"1대지: 평강 (에이레네 — 하나님과의 화해)", "내용":"평강은 에베소서의 첫 번째 선물이다. 그리스도 안에서 하나님과 화해하고 중간 막힌 담이 허물어진 평강이다(엡 2:14). 이 평강이 모든 형제에게 있기를 소원한다", "예화_적용":"오랜 적이 화해한 이야기처럼 그리스도 안에서 하나님과 화해하는 기쁨"},
        {"대지":"2대지: 사랑 (아가페 — 복음적 사랑)", "내용":"아가페 사랑은 에베소서의 두 번째 선물이다. 그리스도의 사랑이 우리를 사랑하게 하고 우리가 서로 사랑하게 한다. 이 사랑이 모든 형제에게 흘러가기를 소원한다", "예화_적용":"그리스도의 사랑을 받은 자가 이웃을 사랑하게 되는 연쇄 반응 이야기"},
        {"대지":"3대지: 믿음 (피스티스 — 그리스도에 대한 신뢰)", "내용":"믿음은 에베소서의 세 번째 선물이다. 은혜로 구원받는 믿음, 역경 중에서도 흔들리지 않는 믿음이 모든 형제에게 있기를 소원한다", "예화_적용":"평강과 사랑을 가능하게 하는 믿음의 기초 — 믿음이 없이는 평강도 사랑도 유지될 수 없다"},
        {"대지":"결론", "내용":"평강과 믿음과 사랑이 하나님 아버지와 주 예수 그리스도로부터 당신에게 있을지어다. 이것이 에베소서가 당신에게 남기는 축복이다. 이 세 가지를 받아 삶으로 살아가라", "예화_적용":"기도 결단: 에베소서의 가르침대로 평강을 살고 사랑을 실천하고 믿음을 지키겠다는 결단 기도"}
    ],
    표7_찬송가: [
        {"새찬송가":"559", "통일찬송가":"496", "제목":"주 안에 있는 나에게", "선정이유":"주 안에서 평강과 사랑을 누리는 신앙의 기쁨을 노래하는 찬송"},
        {"새찬송가":"430", "통일찬송가":"391", "제목":"나 같은 죄인 살리신", "선정이유":"하나님의 은혜와 사랑으로 평강을 얻은 감사의 고백"},
        {"새찬송가":"312", "통일찬송가":"228", "제목":"기뻐하며 경배하세", "선정이유":"하나님의 복을 받아 기쁨으로 경배하는 찬송"},
        {"새찬송가":"204", "통일찬송가":"193", "제목":"내 구주 예수를 더욱 사랑", "선정이유":"믿음과 사랑이 깊어지기를 바라는 헌신의 찬송"}
    ],
    표8_상담적용: [
        {"상황":"평강이 없어 불안한 성도 상담", "성경원리":"평강은 하나님 아버지와 주 예수 그리스도로부터 온다. 인간의 노력이 아닌 하나님과의 관계 회복에서 평강이 온다", "실제적용":"하나님과의 관계를 점검하기, 빌 4:7의 평강이 지키는 원리 적용하기"},
        {"상황":"교회 안에서 사랑이 식어가는 공동체 상담", "성경원리":"사랑(아가페)은 하나님으로부터 온다. 하나님의 사랑을 받은 공동체가 서로를 사랑할 수 있다. 하나님의 사랑을 다시 받는 것이 공동체 사랑의 회복이다", "실제적용":"함께 하나님의 사랑을 묵상하는 예배 시간 갖기, 서로 사랑을 표현하는 공동체 문화 만들기"},
        {"상황":"믿음이 흔들리는 성도 상담", "성경원리":"믿음도 하나님으로부터 온다. 흔들리는 믿음은 하나님께 더 많은 믿음을 구하는 기도의 계기가 되어야 한다", "실제적용":"눅 17:5처럼 믿음을 더해달라고 기도하기, 믿음이 강한 공동체와 함께하기"}
    ],
    표9_교차참조: [
        {"구절":"민 6:24-26", "연결점":"아론의 제사장적 축복 — 여호와께서 네게 복을 주시고 지키시기를 원하며 평강 주시기를 원하노라 — 에베소서 축복의 구약 원형", "구분":"구약"},
        {"구절":"시 29:11", "연결점":"여호와께서 자기 백성에게 힘을 주심이여 여호와께서 자기 백성에게 평강의 복을 주시리로다", "구분":"구약"},
        {"구절":"사 9:6", "연결점":"그 이름은 평강의 왕이라 — 그리스도가 평강의 원천이라는 예언", "구분":"구약"},
        {"구절":"창 49:28", "연결점":"야곱이 아들들에게 각각 그 기업대로 축복한 것이 형제들에 대한 복 선언의 구약 원형", "구분":"구약"},
        {"구절":"엡 1:2", "연결점":"은혜와 평강이 하나님 아버지와 주 예수 그리스도로부터 — 에베소서의 인사말과 마지막 축복의 수미쌍관 구조", "구분":"신약"},
        {"구절":"빌 4:7", "연결점":"하나님의 평강이 모든 지각에 뛰어나 마음과 생각을 지키리라 — 평강의 내용과 능력에 대한 병행 선언", "구분":"신약"},
        {"구절":"갈 5:6", "연결점":"그리스도 예수 안에서는 사랑으로써 역사하는 믿음뿐이니라 — 믿음과 사랑의 통합", "구분":"신약"},
        {"구절":"고후 13:13", "연결점":"주 예수 그리스도의 은혜와 하나님의 사랑과 성령의 교통하심이 너희 무리와 함께 있을지어다 — 삼위일체적 축복의 병행", "구분":"신약"}
    ]
};

pastorCommentaryData["에베소서_6_24"] = {
    본문: "변함이 없이 우리 주 예수 그리스도를 사랑하는 모든 자에게 은혜가 있을지어다",
    표1_원어분석: [
        {"원어":"헤 카리스 메타 판톤 톤 아가폰탄 (ἡ χάρις μετὰ πάντων τῶν ἀγαπώντων)", "의미_문법":"은혜가 모든 사랑하는 자들에게 - 소원문, 현재 능동 분사 복수", "설교포인트":"은혜는 그리스도를 사랑하는 자들 위에 임하는 하나님의 선물이다"},
        {"원어":"엔 아프타르시아 (ἐν ἀφθαρσίᾳ)", "의미_문법":"썩지 않음 안에서, 변함없이 - 여격 명사, 불멸성·순수성 의미", "설교포인트":"참된 사랑은 변함없고 순수하며 영원하다"},
        {"원어":"톤 아가리온 헤몬 이에수 크리스톤 (τὸν κύριον ἡμῶν Ἰησοῦν Χριστόν)", "의미_문법":"우리 주 예수 그리스도를 - 대격, 사랑의 대상", "설교포인트":"그리스도에 대한 사랑이 은혜의 수혜 조건이 아닌 은혜의 열매다"}
    ],
    표2_역사적배경: [
        {"항목":"서신 마감 관습", "내용":"당시 헬레니즘 서신은 '카리스(χάρις, 은혜)'로 시작하고 마치는 관습이 있었으며, 바울은 이를 기독교적으로 재해석하여 그리스도 중심의 축도로 변형하였다", "목회적활용":"예배의 시작과 끝에 은혜를 선언하듯, 삶의 모든 순간을 은혜의 틀 안에서 해석하도록 가르치라"},
        {"항목":"옥중 서신의 종결", "내용":"에베소서는 바울이 로마 감옥에서 기록한 옥중 서신으로, 쇠사슬에 매인 상황에서도 성도들을 향한 은혜의 축원으로 마친다는 점에서 깊은 신앙적 감동을 준다", "목회적활용":"고난 중에도 타인을 위해 은혜를 빌 수 있는 신앙의 성숙을 도전하라"},
        {"항목":"'아프타르시아' 용어의 신학적 맥락", "내용":"'아프타르시아(ἀφθαρσία)'는 고린도전서 15장에서 부활의 특성(썩지 아니함)을 묘사할 때 사용된 단어로, 성도의 그리스도를 향한 사랑이 부활 생명과 같이 영원하고 변함없음을 함의한다", "목회적활용":"그리스도를 향한 사랑이 세상의 변화에 흔들리지 않도록 영원한 관점을 가르치라"}
    ],
    표3_신학적의미: [
        {"교리":"은혜론 (Gratia)", "설명":"은혜는 하나님께서 사랑하는 자들에게 값없이 베푸시는 선물로, 에베소서 전체(1:2)가 은혜로 시작하여 은혜(6:24)로 마친다. 이는 구원의 알파와 오메가가 하나님의 은혜임을 선언한다", "관련구절":"엡 1:2, 2:8-9, 고후 13:14"},
        {"교리":"성도의 견인과 사랑의 항구성", "설명":"'변함없이' 사랑하는 자들에게 은혜가 임한다는 것은 성도의 참된 사랑이 일시적 감정이 아닌 변치 않는 헌신임을 강조한다. 이는 성도의 견인 교리와 연결되며, 끝까지 사랑하는 자에게 은혜가 함께함을 선언한다", "관련구절":"요 13:1, 롬 8:35-39, 딤후 4:8"},
        {"교리":"그리스도 중심성", "설명":"모든 은혜는 '우리 주 예수 그리스도'를 통해 주어진다. 에베소서가 그리스도의 몸인 교회론으로 전개되다가 그리스도를 사랑하는 자들에게 은혜를 축원함으로 마치는 것은 서신 전체의 그리스도 중심성을 완성한다", "관련구절":"요 1:17, 롬 5:15, 엡 1:3"}
    ],
    표4_예표론: [
        {"구분":"대제사장의 축복", "내용":"아론의 제사장 축복(민 6:24-26)은 이스라엘 백성에게 하나님의 은혜와 평강을 선언하는 의식으로, 구약의 축복 구조를 보여준다", "그리스도연결":"그리스도는 더 나은 대제사장으로(히 4:14-16), 그의 이름으로 하나님의 은혜가 모든 성도에게 임한다 (엡 6:24)"},
        {"구분":"솔로몬의 성전 봉헌 축복", "내용":"솔로몬은 성전 봉헌 후 온 회중에게 하나님의 은혜와 복이 함께하기를 축원하였다(왕상 8:55-61). 이는 공동체 전체를 향한 은혜의 선포다", "그리스도연결":"에베소서의 마지막 축도는 교회 공동체 전체를 향한 은혜의 선포로, 그리스도 안에서 새로운 성전인 교회에 임하는 은혜를 완성한다 (엡 2:21-22)"},
        {"구분":"모세의 마지막 축복", "내용":"신명기 33장에서 모세는 각 지파를 위한 마지막 축복을 선언하며 사역을 마쳤다. 이는 지도자가 공동체를 위해 마지막까지 축복하는 패턴이다", "그리스도연결":"바울은 옥중에서 에베소 교회에 마지막 은혜를 축원함으로, 그리스도 안에서의 사역자적 사랑을 완성한다 (엡 6:24)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"Grace be with all them that love our Lord Jesus Christ in sincerity. The apostle wishes grace to all who love Christ in sincerity, that is, with a pure and incorruptible love, not mixed with worldly or self-interested views.", "한국어번역":"우리 주 예수 그리스도를 변함없이 사랑하는 모든 자에게 은혜가 있을지어다. 사도는 그리스도를 진실되게, 즉 세상적이거나 자기 이익적인 관점이 섞이지 않은 순수하고 썩지 않는 사랑으로 사랑하는 모든 자에게 은혜를 빈다", "핵심통찰":"참된 그리스도 사랑은 순수하고 이해관계를 초월한 헌신이어야 한다"},
        {"영어원문":"This is the character of all true Christians; they love Jesus Christ in sincerity. Their love to him is not a mere show and pretense, but real and hearty; not wavering but constant; not mercenary but free and genuine.", "한국어번역":"이것이 모든 참된 그리스도인의 특성이다. 그들은 예수 그리스도를 진실되게 사랑한다. 그리스도를 향한 그들의 사랑은 단순한 겉치레가 아니라 진실하고 진심에서 우러나온 것이며, 흔들리지 않고 변함없으며, 이해관계를 따르지 않고 자유롭고 순수하다", "핵심통찰":"그리스도인의 정체성은 예수를 진심으로, 변함없이, 순수하게 사랑하는 것에 있다"},
        {"영어원문":"The apostle concludes with this general blessing, wishing grace to all who truly love Christ. This is the sum and substance of all good wishes: grace from God, flowing through Christ, resting on all believers.", "한국어번역":"사도는 참으로 그리스도를 사랑하는 모든 자에게 은혜를 비는 이 일반적 축복으로 서신을 마친다. 이것이 모든 선한 소원의 요약이자 본질이다: 하나님으로부터 흘러나와 그리스도를 통해 모든 신자들 위에 안식하는 은혜", "핵심통찰":"은혜는 하나님에게서 발원하여 그리스도를 통해 모든 믿는 자에게 흘러간다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"변함없는 사랑 위에 임하는 은혜 (에베소서 6:24)", "예화_적용":"에베소서 전체가 은혜로 시작하여 은혜로 마치듯, 성도의 삶도 은혜로 시작하고 은혜로 완성된다"},
        {"대지":"서론", "내용":"바울은 로마 감옥에서 쇠사슬에 묶인 채로도 에베소 성도들을 향해 은혜를 축원하며 서신을 마친다. 오늘 본문은 에베소서의 마지막 절로, '변함없는 사랑'과 '은혜'라는 두 핵심 주제가 아름답게 만나는 절정이다", "예화_적용":"찰스 스펄전은 '은혜로 시작하고 은혜로 끝나는 삶이 복된 삶'이라고 했다. 우리의 하루, 우리의 삶, 우리의 신앙도 은혜로 시작하고 은혜로 마쳐야 한다"},
        {"대지":"1대지: 변함없는 사랑의 특성 (아프타르시아)", "내용":"'변함없이(ἐν ἀφθαρσίᾳ)'는 썩지 않음, 불변성을 뜻한다. 세상의 모든 것은 변하지만 그리스도를 향한 참된 사랑은 영원하다. 이 사랑은 감정이 아닌 의지적 헌신이며, 상황에 흔들리지 않는 뿌리 깊은 신앙에서 나온다", "예화_적용":"순교자 폴리카르포스는 죽음 앞에서도 '나는 86년간 그분을 섬겼으며 그분은 나를 해치신 적이 없다. 어떻게 나를 구원하신 왕을 모독할 수 있겠는가'라고 외쳤다. 이것이 변함없는 사랑이다"},
        {"대지":"2대지: 은혜의 수혜자는 사랑하는 자 (모든 자에게)", "내용":"은혜는 그리스도를 사랑하는 '모든 자'에게 임한다. 특정 지위나 능력이 아닌, 그리스도를 향한 사랑이 은혜의 통로다. 이는 은혜가 인간의 공로로 얻는 것이 아니라 그리스도와의 사랑 관계 안에서 주어지는 선물임을 가르친다", "예화_적용":"청지기 비유에서 주인이 돌아올 때 신실하게 섬긴 종에게 더 많은 것을 위탁했듯(마 25:21), 그리스도를 변함없이 사랑하는 자에게 하나님의 은혜는 더욱 풍성히 임한다"},
        {"대지":"3대지: 은혜는 우리 주 예수 그리스도로부터 (그리스도 중심)", "내용":"모든 은혜의 근원은 '우리 주 예수 그리스도'이다. 에베소서 1:3에서 '그리스도 안에서 하늘에 속한 모든 신령한 복'이 시작되었듯, 6:24에서 은혜가 그리스도 안에서 마친다. 구원의 처음과 끝이 모두 그리스도이심을 선언한다", "예화_적용":"바흐는 모든 악보의 끝에 'SDG(Soli Deo Gloria, 오직 하나님께 영광)'를 기록했다. 에베소서의 마지막 절도 모든 은혜가 그리스도로부터 임한다는 선언으로, 하나님께 모든 영광을 돌린다"},
        {"대지":"결론", "내용":"에베소서는 하늘의 모든 신령한 복을 받은 성도들의 이야기다(1:3). 그 은혜의 여정이 마지막에 '그리스도를 변함없이 사랑하는 자들에게 은혜가 있으라'는 축원으로 완성된다. 우리의 신앙은 은혜로 시작하여 은혜로 자라나 은혜로 완성된다. 오늘도, 내일도, 영원토록 그 은혜가 우리 위에 임한다", "예화_적용":"예배를 마칠 때 선언하는 축도처럼, 이 말씀을 가슴에 품고 세상으로 나가라. 변함없는 사랑으로 주를 사랑하는 자에게 은혜는 매일 새롭게 임할 것이다"}
    ],
    표7_찬송가: [
        {"새찬송가":"310", "통일찬송가":"410", "제목":"아 하나님의 은혜로", "선정이유":"하나님의 은혜로 구원받고 살아가는 감사를 노래하며, '은혜가 있을지어다'는 축원과 직결됨"},
        {"새찬송가":"304", "통일찬송가":"404", "제목":"그 크신 하나님의 사랑", "선정이유":"변함없이 우리를 사랑하시는 하나님의 사랑을 찬양하며, 본문의 '변함없는 사랑' 주제를 노래함"},
        {"새찬송가":"559", "통일찬송가":"496", "제목":"주 안에 있는 나에게", "선정이유":"주 안에서 누리는 은혜와 평안을 노래하며, 에베소서 전체의 결론인 그리스도 안의 은혜를 표현함"},
        {"새찬송가":"428", "통일찬송가":"388", "제목":"내 주를 가까이 하게 함은", "선정이유":"주를 더욱 가까이 사랑하며 나아가는 신앙의 여정을 담아, '그리스도를 사랑하는 자'의 모습을 표현함"}
    ],
    표8_상담적용: [
        {"상황":"신앙이 식어가며 그리스도에 대한 사랑을 잃어버린 성도", "성경원리":"'변함없이 우리 주 예수 그리스도를 사랑하는 자에게 은혜가 있다'(엡 6:24). 참된 사랑은 감정이 아닌 의지적 헌신이며, 그 사랑을 회복할 때 은혜도 새롭게 임한다", "실제적용":"요한계시록 2:4-5의 '처음 사랑'으로 돌아가도록 권면하라. 그리스도를 처음 만났을 때의 감사와 경외를 떠올리고, 말씀 묵상과 기도로 사랑의 불씨를 다시 지피도록 돕는다"},
        {"상황":"고난과 시련으로 하나님의 은혜를 의심하는 성도", "성경원리":"바울은 옥중에서도 은혜를 축원했다(엡 6:20, 24). 은혜는 환경이 좋을 때만 임하는 것이 아니라 그리스도를 사랑하는 자에게 언제나 함께한다", "실제적용":"고난 중에도 하나님의 은혜를 확인한 성경의 인물들(욥, 요셉, 바울)의 이야기를 나누고, 현재의 어려움 속에서도 역사하시는 은혜의 흔적을 함께 찾아보라"},
        {"상황":"교회 공동체 안에서 관계의 상처를 입은 성도", "성경원리":"에베소서 전체가 교회 공동체의 하나됨(4:3)과 그리스도 안의 은혜(6:24)를 가르친다. 은혜는 공동체 안에서 서로를 용서하고 사랑할 때 더욱 풍성해진다", "실제적용":"상처받은 마음을 인정하고 공감하되, 에베소서 4:32의 '서로 용서하기를 하나님이 그리스도 안에서 너희를 용서하심같이 하라'는 말씀으로 용서와 화해의 길을 찾도록 함께 기도하라"}
    ],
    표9_교차참조: [
        {"구절":"민 6:24-26", "연결점":"아론의 축복 선언 '여호와는 네게 복을 주시고 너를 지키시기를 원하며'는 구약의 은혜 축원이며, 에베소서 마지막 절의 은혜 축원과 평행한다", "구분":"구약"},
        {"구절":"시 36:7", "연결점":"'하나님이여 주의 인자하심이 어찌 그리 보배로우신지요 사람들이 주의 날개 그늘 아래 피하나이다' - 하나님의 변함없는 사랑(헤세드)은 에베소서의 '은혜'와 연결된다", "구분":"구약"},
        {"구절":"신 7:9", "연결점":"'신실하신 하나님이시라 그를 사랑하고 그의 계명을 지키는 자에게는 천 대까지 그의 언약을 이행하시며 인애를 베푸시되' - 하나님을 사랑하는 자에게 임하는 언약적 은혜", "구분":"구약"},
        {"구절":"애 3:22-23", "연결점":"'여호와의 인자와 긍휼이 무궁하시므로 우리가 진멸되지 아니함이니이다 이것들이 아침마다 새로우니' - 하나님의 은혜의 변함없음과 매일의 새로움", "구분":"구약"},
        {"구절":"요 14:21", "연결점":"'나의 계명을 지키는 자라야 나를 사랑하는 자니 나를 사랑하는 자는 내 아버지께 사랑을 받을 것이요 나도 그를 사랑하여 그에게 나를 나타내리라' - 그리스도를 사랑하는 자에게 임하는 하나님의 사랑", "구분":"신약"},
        {"구절":"롬 8:38-39", "연결점":"'내가 확신하노니 사망이나 생명이나... 다른 아무 피조물이라도 우리를 우리 주 그리스도 예수 안에 있는 하나님의 사랑에서 끊을 수 없으리라' - 변함없는 하나님의 사랑이 은혜의 근거", "구분":"신약"},
        {"구절":"고후 13:14", "연결점":"'주 예수 그리스도의 은혜와 하나님의 사랑과 성령의 교통하심이 너희 무리와 함께 있을지어다' - 바울의 다른 서신의 은혜 축원으로 에베소서 마지막 절과 평행한다", "구분":"신약"},
        {"구절":"계 22:21", "연결점":"'주 예수의 은혜가 모든 자들에게 있을지어다 아멘' - 성경 전체의 마지막 축원이 에베소서 6:24의 은혜 축원과 일치하며, 은혜가 구원사의 결론임을 선언한다", "구분":"신약"}
    ]
};
